__attribute__((used))
inline const uint16_t* mascotFrame(Mood m, uint8_t frame) {
  frame = frame % 2;
  switch (m) {
    case Mood::HAPPY:
      return frame ? SPRITE_HAPPY_1 : SPRITE_HAPPY_0;
    case Mood::UNEASY:
      return frame ? SPRITE_UNEASY_1 : SPRITE_UNEASY_0;
    case Mood::STRESSED:
      return frame ? SPRITE_STRESSED_1 : SPRITE_STRESSED_0;
    case Mood::PANIC:
      return frame ? SPRITE_PANIC_1 : SPRITE_PANIC_0;
    case Mood::SLEEPING:
      return frame ? SPRITE_SLEEPING_1 : SPRITE_SLEEPING_0;
    case Mood::OFFLINE:
      return frame ? SPRITE_OFFLINE_1 : SPRITE_OFFLINE_0;
  }
  return SPRITE_OFFLINE_0;
}
